mapper.select:
SELECT cp.id, cp.user_id as userId, u.name as author, cp.category, cp.title, cp.content, cp.view_count as viewCount, cp.comment_count as commentCount, cp.tags, DATE_FORMAT(cp.created_at, '%Y-%m-%d %H:%i:%s') as createdAt, DATE_FORMAT(cp.updated_at, '%Y-%m-%d %H:%i:%s') as updatedAt FROM community_posts cp LEFT JOIN users u ON cp.user_id = u.id WHERE cp.deleted_at IS NULL
AND (cp.title LIKE CONCAT('%', #{search}, '%') OR cp.content LIKE CONCAT('%', #{search}, '%'))
AND cp.category = #{category} ORDER BY cp.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM community_posts WHERE deleted_at IS NULL
AND (title LIKE CONCAT('%', #{search}, '%') OR content LIKE CONCAT('%', #{search}, '%'))
AND category = #{category}
